def chart(key):
 d=charts[key];rows=[]
 for i,r in enumerate(d['series']):
  dec=3 if key=='balance_sheet' else (1 if r['value']%1 else 0)
  rows.append(f'<div class="chart-row reveal" data-beat="{4+i*4}"><div class="cat">{r["name"]}</div><div class="plot-cell"><div class="grid"></div><div class="bar" data-frac="{r["value"]/d["axis"]["max"]}"></div><div class="val" data-max="{d["axis"]["max"]}">{count(r["value"],r.get("qualifier",""),dec=dec)}</div></div><div></div></div>')
 ticks=list(range(0,d['axis']['max']+1,d['axis']['step']));axis=''.join(f'<span style="left:{j/(len(ticks)-1)*100}%">{str(v//1000)+"k" if key=="deliveries" and v else v}</span>' for j,v in enumerate(ticks))
 notes=d['notes']
 return '<div class="chart '+key+'" style="--gridstep:'+str(d['axis']['step']/d['axis']['max']*100)+'%">'+''.join(rows)+f'<div class="axis reveal" data-beat="0"><div></div><div class="ticks">{axis}</div><div></div></div><div class="unit reveal" data-beat="0">{d["unit"]}</div><div class="chart-note reveal" data-beat="0">'+''.join(f'<div>{x}</div>' for x in notes)+'</div></div>'
