js='''const SPEC=__SPEC__,CAPTIONS=__CAPTIONS__;const DURATION=SPEC.duration,FPS=30,T=60/122,bt=b=>Math.round(b*T*FPS)/FPS;
window.__timelines=window.__timelines||{};const tl=gsap.timeline({paused:true});const counters=[],anchors=[];
SPEC.beats.slice(0,-1).forEach((beat,i)=>{const s=document.getElementById('s'+i),start=bt(beat),next=bt(SPEC.beats[i+1]);
 // Page-plane turn alternates with full slide/push. The outgoing page stays underneath during the transition.
 if(i%3===1)tl.fromTo(s,{opacity:1,rotationY:-74,x:110},{opacity:1,rotationY:0,x:0,duration:2*T,ease:'power3.out',immediateRender:false},start);
 else if(i%3===2)tl.fromTo(s,{opacity:1,x:1920},{opacity:1,x:0,duration:2*T,ease:'power3.out',immediateRender:false},start);
 else tl.fromTo(s,{opacity:0,y:40},{opacity:1,y:0,duration:2*T,ease:'power2.out',immediateRender:false},start);
 if(i<11)tl.to(s,{opacity:0,duration:.01},next+2*T);
 s.querySelectorAll('.reveal').forEach(el=>{const at=bt(beat+Number(el.dataset.beat||0));anchors.push({beat:beat+Number(el.dataset.beat||0),time:at,scene:i});const block=el.matches('.panel,.tag,.node,.tile,.lesson,.margin-box,.big-tile,.strip');tl.fromTo(el,{opacity:0,y:block?0:18,x:block?-100:0},{opacity:1,y:0,x:0,duration:block?2*T:.55,ease:'power2.out',immediateRender:false},at);});
 s.querySelectorAll('.bar').forEach(el=>{const at=bt(beat+Number(el.closest('.reveal').dataset.beat));tl.fromTo(el,{scaleX:0},{scaleX:Number(el.dataset.frac),duration:4*T,ease:'power2.out',immediateRender:false},at);});
 s.querySelectorAll('.count').forEach(el=>{const at=bt(beat+Number(el.closest('.reveal')?.dataset.beat||4));counters.push({el,start:at,end:at+4*T,v:Number(el.dataset.v),pre:el.dataset.pre||'',suf:el.dataset.suf||'',dec:Number(el.dataset.dec||0)});});
 const car=s.querySelector('.car');if(car){tl.fromTo(car,{opacity:0,x:-50},{opacity:1,x:0,duration:4*T,ease:'power2.out',immediateRender:false},bt(beat+8));tl.to(car,{x:45,duration:12*T,ease:'sine.inOut'},bt(beat+12));}
 tl.to('#moving-block',{x:i%2?1080:0,scaleX:i%3===0?1:.48,duration:4*T,ease:'power3.inOut'},start);
 tl.to('#side-block',{y:(i%3)*190,height:i%2?140:80,duration:4*T,ease:'power2.inOut'},start);
});
const matrix=[...document.querySelectorAll('.matrix i')];matrix.forEach((el,i)=>{tl.fromTo(el,{opacity:0,scale:.7},{opacity:.6,scale:1,duration:.6,ease:'power2.out'},bt(4)+i*.025);if(i%5!==0)tl.to(el,{opacity:.08,duration:1.3,ease:'power1.out'},bt(12)+i*.008);});
const cap=document.querySelector('#captions span');function updateText(time){counters.forEach(c=>{const v=c.v*(1-Math.pow(1-Math.max(0,Math.min(1,(time-c.start)/(c.end-c.start))),3));c.el.textContent=c.pre+(c.dec?v.toFixed(c.dec):Math.round(v).toLocaleString('en-US'))+c.suf;const label=c.el.closest('.val');if(label)label.style.left=(v/Number(label.dataset.max)*100)+'%';});const line=CAPTIONS.find(c=>time>=c.start&&time<c.end);cap.textContent=line?line.text:'';}
tl.eventCallback('onUpdate',()=>updateText(tl.time()));window.__timelines['uniland-ev-finance']=tl;window.FILM={spec:SPEC,anchors,captions:CAPTIONS,seek:time=>{const t=Math.max(0,Math.min(DURATION,Math.round(time*FPS)/FPS));tl.time(t);updateText(t);}};
'''.replace('__SPEC__',json.dumps(dict(beats=BEATS,duration=D,width=1920,height=1080,fps=30,bpm=122))).replace('__CAPTIONS__',json.dumps(json.loads((p/'work/timing.json').read_text())))
