player=player.replace('(innerWidth-40)/1080','(innerWidth-40)/1920').replace('(innerHeight-190)/1920','(innerHeight-190)/1080').replace('(1080*s)','(1920*s)').replace('(1920*s)+\'px\';}\nwindow','(1080*s)+\'px\';}\nwindow').replace("width='1080px'","width='1920px'").replace("height='1920px'","height='1080px'")
# explicit viewport resize, to avoid accidental substitutions in copied code
player=re.sub(r'function resize\(\).*?\nwindow.addEventListener',"function resize(){const s=Math.max(.08,Math.min((innerWidth-40)/1920,(innerHeight-190)/1080,1));document.getElementById('composition').style.transform='scale('+s+')';document.getElementById('frame').style.width=(1920*s)+'px';document.getElementById('frame').style.height=(1080*s)+'px';}\nwindow.addEventListener",player,flags=re.S)
