html=f'''<!DOCTYPE html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>UNILAND · EV Capital Cycle · Landscape</title><style>@font-face{{font-family:Finance;src:url(data:font/ttf;base64,{font('brand-regular.ttf')}) format('truetype');font-weight:400}}@font-face{{font-family:Finance;src:url(data:font/ttf;base64,{font('brand-bold.ttf')}) format('truetype');font-weight:700}}{css}</style><body><div id="frame" data-composition-id="uniland-ev-finance" data-start="0" data-duration="{D}" data-width="1920" data-height="1080" data-fps="30"><main id="composition">{''.join(sections)}<div id="moving-block" data-layout-ignore></div><div id="side-block" data-layout-ignore></div><div id="captions"><span></span></div><audio id="voice" data-start="0" data-duration="{D}" data-track-index="4" data-volume="1" src="data:audio/mpeg;base64,{aud('voice.mp3')}"></audio><audio id="music" data-start="0" data-duration="{D}" data-track-index="5" data-volume=".75" src="data:audio/mpeg;base64,{aud('bgm.mp3')}"></audio></main></div><div id="controls"><button id="play">Play</button><button id="replay">Replay</button><input id="seek" type="range" min="0" max="{D}" step="0.0333333333" value="0" aria-label="Playback position"><span id="clock"></span><button id="mute">Mute</button><button id="bgm">BGM on</button><div id="status">Click Play · Slower English narration ·122BPM</div></div><details id="notes"><summary>Sources & production notes</summary>{notes}</details><script>{gsap}</script><script>{js+player}</script></body></html>'''
